import { useState, useEffect, useCallback } from 'react';
import { HiMenuAlt3, HiX } from 'react-icons/hi';

function Navbar() {
    const [showMenu, setShowMenu] = useState(false);

    const scrollToComponent = (componentId) => {
        const component = document.getElementById(componentId);
        if (component) {
            component.scrollIntoView({
                behavior: 'smooth',
                duration: 2000,
                block: 'start',
                inline: 'nearest',
            });
            setShowMenu(false); // Close mobile menu after clicking
        }
    };

    const handleWindowResize = useCallback(() => {
        const screenWidth = window.innerWidth;
        if (screenWidth > 768 && showMenu) {
            setShowMenu(false);
        }
    }, [showMenu]);

    useEffect(() => {
        window.addEventListener('resize', handleWindowResize);
        return () => {
            window.removeEventListener('resize', handleWindowResize);
        };
    }, [handleWindowResize]);


    return (
        <nav className="fixed top-0 left-0 right-0 z-50 glass-effect backdrop-blur-xl bg-[#0F1419]/80 border-b border-[#3B82F6]/20 shadow-2xl">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div className="flex justify-between items-center h-16 sm:h-20">
                    {/* Logo/Brand */}
                    <div className="text-xl sm:text-2xl lg:text-3xl font-bold text-white relative">
                        <span className="text-gradient bg-gradient-to-r from-[#3B82F6] to-[#60A5FA] bg-clip-text text-transparent">
                            Amulya
                        </span>
                        <div className="absolute -bottom-1 left-0 w-full h-0.5 bg-gradient-to-r from-[#3B82F6] to-transparent"></div>
                    </div>

                    {/* Desktop Menu */}
                    <ul className="hidden lg:flex items-center space-x-8 font-medium text-white">
                        <li>
                            <button
                                className="relative px-4 py-2 tracking-wide cursor-pointer text-gray-300 hover:text-white transition-all duration-300 group text-sm font-medium"
                                onClick={() => scrollToComponent('about')}
                            >
                                About
                                <span className="absolute inset-0 rounded-lg bg-[#3B82F6]/10 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></span>
                                <span className="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-0 h-0.5 bg-[#3B82F6] group-hover:w-3/4 transition-all duration-300"></span>
                            </button>
                        </li>
                        <li>
                            <button
                                className="relative px-4 py-2 tracking-wide cursor-pointer text-gray-300 hover:text-white transition-all duration-300 group text-sm font-medium"
                                onClick={() => scrollToComponent('experience')}
                            >
                                Experience
                                <span className="absolute inset-0 rounded-lg bg-[#3B82F6]/10 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></span>
                                <span className="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-0 h-0.5 bg-[#3B82F6] group-hover:w-3/4 transition-all duration-300"></span>
                            </button>
                        </li>
                        <li>
                            <button
                                className="relative px-4 py-2 tracking-wide cursor-pointer text-gray-300 hover:text-white transition-all duration-300 group text-sm font-medium"
                                onClick={() => scrollToComponent('skills')}
                            >
                                Skills
                                <span className="absolute inset-0 rounded-lg bg-[#3B82F6]/10 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></span>
                                <span className="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-0 h-0.5 bg-[#3B82F6] group-hover:w-3/4 transition-all duration-300"></span>
                            </button>
                        </li>
                        <li>
                            <button
                                className="relative px-4 py-2 tracking-wide cursor-pointer text-gray-300 hover:text-white transition-all duration-300 group text-sm font-medium"
                                onClick={() => scrollToComponent('projects')}
                            >
                                Projects
                                <span className="absolute inset-0 rounded-lg bg-[#3B82F6]/10 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></span>
                                <span className="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-0 h-0.5 bg-[#3B82F6] group-hover:w-3/4 transition-all duration-300"></span>
                            </button>
                        </li>
                        <li>
                            <button
                                className="relative px-4 py-2 tracking-wide cursor-pointer text-gray-300 hover:text-white transition-all duration-300 group text-sm font-medium"
                                onClick={() => scrollToComponent('achievements')}
                            >
                                Achievements
                                <span className="absolute inset-0 rounded-lg bg-[#3B82F6]/10 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></span>
                                <span className="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-0 h-0.5 bg-[#3B82F6] group-hover:w-3/4 transition-all duration-300"></span>
                            </button>
                        </li>

                    </ul>

                    {/* Mobile Menu Button */}
                    <button
                        className="lg:hidden text-gray-300 hover:text-[#3B82F6] transition-all duration-300 p-2 rounded-lg hover:bg-[#3B82F6]/10"
                        onClick={() => setShowMenu(!showMenu)}
                        aria-label="Toggle menu"
                    >
                        {showMenu ? <HiX size={28} /> : <HiMenuAlt3 size={28} />}
                    </button>
                </div>

                {/* Mobile Menu */}
                {showMenu && (
                    <div className="md:hidden bg-[#20262E] border-t border-gray-700/50 shadow-lg">
                        <ul className="py-6 space-y-2">
                            <li>
                                <button
                                    className="w-full text-left block px-6 py-4 text-white text-lg font-medium hover:text-[#6699CC] hover:bg-gray-700/30 transition-all duration-300 cursor-pointer rounded-lg mx-2"
                                    onClick={() => scrollToComponent('about')}
                                >
                                    About
                                </button>
                            </li>
                            <li>
                                <button
                                    className="w-full text-left block px-6 py-4 text-white text-lg font-medium hover:text-[#6699CC] hover:bg-gray-700/30 transition-all duration-300 cursor-pointer rounded-lg mx-2"
                                    onClick={() => scrollToComponent('experience')}
                                >
                                    Experience
                                </button>
                            </li>
                            <li>
                                <button
                                    className="w-full text-left block px-6 py-4 text-white text-lg font-medium hover:text-[#6699CC] hover:bg-gray-700/30 transition-all duration-300 cursor-pointer rounded-lg mx-2"
                                    onClick={() => scrollToComponent('skills')}
                                >
                                    Skills
                                </button>
                            </li>
                            <li>
                                <button
                                    className="w-full text-left block px-6 py-4 text-white text-lg font-medium hover:text-[#6699CC] hover:bg-gray-700/30 transition-all duration-300 cursor-pointer rounded-lg mx-2"
                                    onClick={() => scrollToComponent('projects')}
                                >
                                    Projects
                                </button>
                            </li>
                            <li>
                                <button
                                    className="w-full text-left block px-6 py-4 text-white text-lg font-medium hover:text-[#6699CC] hover:bg-gray-700/30 transition-all duration-300 cursor-pointer rounded-lg mx-2"
                                    onClick={() => scrollToComponent('achievements')}
                                >
                                    Achievements
                                </button>
                            </li>

                        </ul>
                    </div>
                )}
            </div>
        </nav>
    );
}

export default Navbar;
